1	package net.officefloor.hq.app.clients;
2	
3	import java.math.BigDecimal;
4	import java.util.List;
5	import java.util.regex.Pattern;
6	import net.officefloor.hq.app.Audit;
7	import org.springframework.jdbc.core.JdbcTemplate;
8	import org.springframework.stereotype.Service;
9	import org.springframework.transaction.annotation.Transactional;
10	
11	/** Business logic for clients. Each call runs in its own transaction. */
12	@Service
13	public class ClientService {
14	
15	    // A client must carry a proper email address (mirrors the front-end guard).
16	    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
17	
18	    private final ClientRepository repository;
19	    private final ContactRepository contacts;
20	    private final JdbcTemplate jdbc;
21	    private final Audit audit;
22	
23	    public ClientService(ClientRepository repository, ContactRepository contacts, JdbcTemplate jdbc,
24	            Audit audit) {
25	        this.repository = repository;
26	        this.contacts = contacts;
27	        this.jdbc = jdbc;
28	        this.audit = audit;
29	    }
30	
31	    /** List the clients still in play. Archived clients are tucked away and omitted. */
32	    @Transactional(readOnly = true)
33	    public List<Client> list() {
34	        return repository.findByArchivedFalseOrderByIdAsc();
35	    }
36	
37	    /**
38	     * Clients whose name contains {@code query} (case-insensitive); all clients when blank. Archived
39	     * clients are tucked away, so they drop off the search too.
40	     */
41	    @Transactional(readOnly = true)
42	    public List<Client> search(String query) {
43	        if (query == null || query.isBlank()) {
44	            return list();
45	        }
46	        return repository.findByArchivedFalseAndNameContainingIgnoreCaseOrderByIdAsc(query.trim());
47	    }
48	
49	    /**
50	     * Archive a client: keep the row (and everything hanging off it) but flag it so it drops off the
51	     * list and search. Records an audit entry so the action can be checked later, and returns the
52	     * clients that remain visible.
53	     */
54	    @Transactional
55	    public List<Client> archive(Long id) {
56	        if (id == null) {
57	            throw new IllegalArgumentException("A client id is required to archive");
58	        }
59	        jdbc.update("UPDATE clients SET archived = TRUE WHERE id = ?", id);
60	        audit.record("CLIENT_ARCHIVED id=" + id);
61	        return list();
62	    }
63	
64	    /**
65	     * The projects done for a client, oldest first. By default only ACTIVE, non-archived projects —
66	     * the work still in play — are returned; pass {@code includeAll} to also surface the finished and
67	     * archived (hidden) ones (how the client page's "show all" toggle reveals them). Reads the
68	     * {@code projects} table via SQL so the clients feature stays self-contained and does not import
69	     * the projects feature's Java types.
70	     */
71	    @Transactional(readOnly = true)
72	    public List<ClientProjectView> projectsFor(Long clientId, boolean includeAll) {
73	        String filter = includeAll ? "" : " AND status = 'ACTIVE' AND archived = FALSE";
74	        return jdbc.query(
75	                "SELECT id, name FROM projects WHERE client_id = ?" + filter + " ORDER BY id ASC",
76	                (rs, i) -> new ClientProjectView(rs.getLong("id"), rs.getString("name")),
77	                clientId);
78	    }
79	
80	    /**
81	     * At-a-glance counts for a client's page: how many projects and contacts they have. Counts in
82	     * SQL so a large client doesn't have to ship its full project/contact lists just to be tallied.
83	     */
84	    @Transactional(readOnly = true)
85	    public ClientCountsView countsFor(Long clientId) {
86	        Long projects = jdbc.queryForObject(
87	                "SELECT COUNT(*) FROM projects WHERE client_id = ? AND archived = FALSE",
88	                Long.class, clientId);
89	        Long contacts = jdbc.queryForObject(
90	                "SELECT COUNT(*) FROM contacts WHERE client_id = ?", Long.class, clientId);
91	        return new ClientCountsView(projects == null ? 0 : projects, contacts == null ? 0 : contacts);
92	    }
93	
94	    /**
95	     * A statement for a client: every invoice raised across all of the client's projects, gathered
96	     * in one place, each with how much is still due (its amount minus whatever has been paid against
97	     * it). The outstanding total is the sum of those dues — what the client still owes. Read via SQL
98	     * so the clients feature stays self-contained and does not import the invoices feature's types.
99	     */
100	    @Transactional(readOnly = true)
101	    public ClientStatementView statementFor(Long clientId) {
102	        List<ClientStatementInvoiceView> invoices = jdbc.query(
103	                "SELECT i.id, p.name AS project_name, i.amount, i.status, "
104	                        + "i.amount - COALESCE((SELECT SUM(pay.amount) FROM payments pay "
105	                        + "WHERE pay.invoice_id = i.id), 0) AS due_amount "
106	                        + "FROM invoices i JOIN projects p ON i.project_id = p.id "
107	                        + "WHERE p.client_id = ? ORDER BY i.id ASC",
108	                (rs, i) -> new ClientStatementInvoiceView(rs.getLong("id"),
109	                        rs.getString("project_name"), rs.getBigDecimal("amount"),
110	                        rs.getString("status"), rs.getBigDecimal("due_amount")),
111	                clientId);
112	        BigDecimal outstanding = invoices.stream().map(ClientStatementInvoiceView::getDue)
113	                .reduce(BigDecimal.ZERO, BigDecimal::add);
114	        return new ClientStatementView(invoices, outstanding);
115	    }
116	
117	    /** The contacts kept for a client, oldest first. */
118	    @Transactional(readOnly = true)
119	    public List<ClientContactView> contactsFor(Long clientId) {
120	        return contacts.findByClientIdOrderByIdAsc(clientId).stream()
121	                .map(c -> new ClientContactView(c.getId(), c.getClientId(), c.getName(),
122	                        c.getEmail(), c.getRole(), c.isPrimary()))
123	                .toList();
124	    }
125	
126	    /**
127	     * Pick a client's one main (primary) contact. Clears the flag across the client's contacts and
128	     * sets it on the chosen one, so exactly one is primary at a time. Returns the client's contacts.
129	     */
130	    @Transactional
131	    public List<ClientContactView> setPrimaryContact(Long clientId, Long contactId) {
132	        if (clientId == null || contactId == null) {
133	            throw new IllegalArgumentException("A client and contact are required");
134	        }
135	        jdbc.update("UPDATE contacts SET is_primary = FALSE WHERE client_id = ?", clientId);
136	        jdbc.update("UPDATE contacts SET is_primary = TRUE WHERE id = ? AND client_id = ?",
137	                contactId, clientId);
138	        return contactsFor(clientId);
139	    }
140	
141	    @Transactional
142	    public ClientContactView createContact(Long clientId, String name, String email, String role) {
143	        if (clientId == null) {
144	            throw new IllegalArgumentException("A contact requires a client");
145	        }
146	        if (name == null || name.isBlank()) {
147	            throw new IllegalArgumentException("A contact requires a name");
148	        }
149	        if (email == null || !EMAIL.matcher(email).matches()) {
150	            throw new IllegalArgumentException("A contact requires a valid email address");
151	        }
152	        Contact contact = new Contact();
153	        contact.setClientId(clientId);
154	        contact.setName(name);
155	        contact.setEmail(email);
156	        contact.setRole(role);
157	        Contact saved = contacts.save(contact);
158	        return new ClientContactView(saved.getId(), saved.getClientId(), saved.getName(),
159	                saved.getEmail(), saved.getRole(), saved.isPrimary());
160	    }
161	
162	    /**
163	     * Correct a client's name and/or email. Validates the email like the create path and keeps the
164	     * no-two-clients-share-an-email rule (allowing the client to keep its own email). Records an
165	     * audit entry so the correction can be checked later, and returns the updated row.
166	     */
167	    @Transactional
168	    public Client update(Long id, String name, String email) {
169	        if (id == null) {
170	            throw new IllegalArgumentException("A client id is required to update");
171	        }
172	        if (name == null || name.isBlank()) {
173	            throw new IllegalArgumentException("A client requires a name");
174	        }
175	        if (email == null || !EMAIL.matcher(email).matches()) {
176	            throw new IllegalArgumentException("A client requires a valid email address");
177	        }
178	        Client client = repository.findById(id)
179	                .orElseThrow(() -> new IllegalArgumentException("No such client: " + id));
