1	package net.officefloor.hq.app.invoices;
2	
3	import java.math.BigDecimal;
4	import java.time.LocalDate;
5	import java.util.List;
6	import net.officefloor.hq.app.Audit;
7	import org.springframework.jdbc.core.JdbcTemplate;
8	import org.springframework.jdbc.core.RowMapper;
9	import org.springframework.stereotype.Service;
10	import org.springframework.transaction.annotation.Transactional;
11	
12	/**
13	 * Business logic for invoices. Invoices are always viewed in the context of their project, so the
14	 * list is scoped by project id. The derived total the UI shows is computed by the front-end from the
15	 * returned rows; this service just surfaces the project's invoices in a stable order. Marking an
16	 * invoice paid flips its status and records an audit entry so the action can be checked later.
17	 */
18	@Service
19	public class InvoiceService {
20	
21	    // An invoice's amount minus whatever has been paid against it is what is still left to pay.
22	    private static final String DUE_AWARE_SELECT =
23	            "SELECT i.id, i.project_id, i.amount, i.status, i.issued_date, i.due_date, i.discount_pct, "
24	                    + "i.amount - COALESCE((SELECT SUM(p.amount) FROM payments p "
25	                    + "WHERE p.invoice_id = i.id), 0) AS due_amount FROM invoices i ";
26	
27	    private static final RowMapper<InvoiceView> INVOICE_MAPPER = (rs, i) -> {
28	        BigDecimal amount = rs.getBigDecimal("amount");
29	        BigDecimal dueAmount = rs.getBigDecimal("due_amount");
30	        return new InvoiceView(rs.getLong("id"), rs.getLong("project_id"), amount,
31	                deriveStatus(rs.getString("status"), amount, dueAmount),
32	                rs.getDate("issued_date").toLocalDate().toString(),
33	                rs.getDate("due_date").toLocalDate().toString(), dueAmount,
34	                rs.getBigDecimal("discount_pct"));
35	    };
36	
37	    /**
38	     * The status we show is worked out from the payments, not flipped by hand: an invoice reads PAID
39	     * once its payments cover the amount, PARTIAL once some (but not all) has been paid, and otherwise
40	     * keeps its stored lifecycle status (DRAFT/SENT).
41	     */
42	    private static String deriveStatus(String stored, BigDecimal amount, BigDecimal dueAmount) {
43	        BigDecimal paid = amount.subtract(dueAmount);
44	        if (paid.signum() <= 0) {
45	            return stored;
46	        }
47	        return dueAmount.signum() <= 0 ? "PAID" : "PARTIAL";
48	    }
49	
50	    private final InvoiceRepository repository;
51	    private final LineItemRepository lineItemRepository;
52	    private final PaymentRepository paymentRepository;
53	    private final JdbcTemplate jdbc;
54	    private final Audit audit;
55	
56	    public InvoiceService(InvoiceRepository repository, LineItemRepository lineItemRepository,
57	            PaymentRepository paymentRepository, JdbcTemplate jdbc, Audit audit) {
58	        this.repository = repository;
59	        this.lineItemRepository = lineItemRepository;
60	        this.paymentRepository = paymentRepository;
61	        this.jdbc = jdbc;
62	        this.audit = audit;
63	    }
64	
65	    /** Every invoice across all projects; narrowed to a single lifecycle stage when {@code status} is given. */
66	    @Transactional(readOnly = true)
67	    public List<AllInvoiceView> listAll(String status) {
68	        RowMapper<AllInvoiceView> mapper = (rs, i) -> new AllInvoiceView(rs.getLong("id"),
69	                rs.getString("project_name"), rs.getBigDecimal("amount"), rs.getString("status"));
70	        String base = "SELECT i.id, i.amount, i.status, p.name AS project_name "
71	                + "FROM invoices i JOIN projects p ON i.project_id = p.id ";
72	        if (status == null || status.isBlank()) {
73	            return jdbc.query(base + "ORDER BY i.id ASC", mapper);
74	        }
75	        return jdbc.query(base + "WHERE i.status = ? ORDER BY i.id ASC", mapper, status.trim());
76	    }
77	
78	    /**
79	     * One page of the cross-project invoice list. The list is large, so it is served a page at a
80	     * time in id order, optionally narrowed to a lifecycle stage. {@code page} is 1-based and
81	     * {@code size} is the page size; both are clamped to sane minimums. The returned view carries
82	     * the page's rows plus the paging metadata (page served, total pages, total rows).
83	     */
84	    @Transactional(readOnly = true)
85	    public AllInvoicesPageView listAllPaged(String status, int page, int size) {
86	        int pageSize = Math.max(1, size);
87	        boolean filtered = status != null && !status.isBlank();
88	        String stage = filtered ? status.trim() : null;
89	
90	        String countSql = "SELECT COUNT(*) FROM invoices i"
91	                + (filtered ? " WHERE i.status = ?" : "");
92	        long total = filtered
93	                ? jdbc.queryForObject(countSql, Long.class, stage)
94	                : jdbc.queryForObject(countSql, Long.class);
95	
96	        int pageCount = total == 0 ? 1 : (int) ((total + pageSize - 1) / pageSize);
97	        int current = Math.min(Math.max(1, page), pageCount);
98	        int offset = (current - 1) * pageSize;
99	
100	        RowMapper<AllInvoiceView> mapper = (rs, i) -> new AllInvoiceView(rs.getLong("id"),
101	                rs.getString("project_name"), rs.getBigDecimal("amount"), rs.getString("status"));
102	        String base = "SELECT i.id, i.amount, i.status, p.name AS project_name "
103	                + "FROM invoices i JOIN projects p ON i.project_id = p.id ";
104	        List<AllInvoiceView> items = filtered
105	                ? jdbc.query(base + "WHERE i.status = ? ORDER BY i.id ASC LIMIT ? OFFSET ?",
106	                        mapper, stage, pageSize, offset)
107	                : jdbc.query(base + "ORDER BY i.id ASC LIMIT ? OFFSET ?",
108	                        mapper, pageSize, offset);
109	        return new AllInvoicesPageView(items, current, pageCount, total);
110	    }
111	
112	    @Transactional(readOnly = true)
113	    public List<InvoiceView> listForProject(Long projectId) {
114	        return jdbc.query(
115	                DUE_AWARE_SELECT + "WHERE i.project_id = ? ORDER BY i.id ASC",
116	                INVOICE_MAPPER, projectId);
117	    }
118	
119	    @Transactional(readOnly = true)
120	    public List<InvoiceView> listForProjectByDueDate(Long projectId) {
121	        return jdbc.query(
122	                DUE_AWARE_SELECT + "WHERE i.project_id = ? ORDER BY i.due_date ASC, i.id ASC",
123	                INVOICE_MAPPER, projectId);
124	    }
125	
126	    @Transactional
127	    public InvoiceView create(Long projectId, BigDecimal amount) {
128	        if (projectId == null) {
129	            throw new IllegalArgumentException("An invoice requires a project");
130	        }
131	        if (amount == null) {
132	            throw new IllegalArgumentException("An invoice requires an amount");
133	        }
134	        if (amount.signum() <= 0) {
135	            throw new IllegalArgumentException("An invoice amount must be greater than zero");
136	        }
137	        Invoice invoice = new Invoice();
138	        invoice.setProjectId(projectId);
139	        invoice.setAmount(amount);
140	        // A new invoice goes out today and is due 30 days later.
141	        LocalDate issued = LocalDate.now();
142	        invoice.setIssuedDate(issued);
143	        invoice.setDueDate(issued.plusDays(30));
144	        Invoice saved = repository.save(invoice);
145	        // A brand-new invoice has had nothing paid against it yet, so the whole amount is due.
146	        return new InvoiceView(saved.getId(), saved.getProjectId(), saved.getAmount(),
147	                saved.getStatus(), saved.getIssuedDate().toString(), saved.getDueDate().toString(),
148	                saved.getAmount(), saved.getDiscountPct());
149	    }
150	
151	    @Transactional
152	    public InvoiceView send(Long invoiceId) {
153	        if (invoiceId == null) {
154	            throw new IllegalArgumentException("An invoice id is required");
155	        }
156	        InvoiceView current = find(invoiceId);
157	        if (!"DRAFT".equals(current.getStatus())) {
158	            throw new IllegalStateException("Only a draft invoice can be sent");
159	        }
160	        jdbc.update("UPDATE invoices SET status = 'SENT' WHERE id = ?", invoiceId);
161	        InvoiceView invoice = find(invoiceId);
162	        audit.record("INVOICE_SENT id=" + invoice.getId() + " amount="
163	                + invoice.getAmount().setScale(2));
164	        return invoice;
165	    }
166	
167	    /**
168	     * Cancel (void) an invoice that was sent by mistake. A voided invoice reads VOID and stops
169	     * counting toward what is owed (the outstanding total only sums SENT invoices). Only a sent
170	     * invoice can be voided; records an audit entry so the action can be checked later.
171	     */
172	    @Transactional
173	    public InvoiceView cancel(Long invoiceId) {
174	        if (invoiceId == null) {
175	            throw new IllegalArgumentException("An invoice id is required");
176	        }
177	        InvoiceView current = find(invoiceId);
178	        if (!"SENT".equals(current.getStatus())) {
179	            throw new IllegalStateException("Only a sent invoice can be cancelled");
180	        }
181	        jdbc.update("UPDATE invoices SET status = 'VOID' WHERE id = ?", invoiceId);
182	        InvoiceView invoice = find(invoiceId);
183	        audit.record("INVOICE_VOIDED id=" + invoice.getId() + " amount="
184	                + invoice.getAmount().setScale(2));
185	        return invoice;
186	    }
187	
188	    @Transactional
189	    public InvoiceView pay(Long invoiceId) {
190	        if (invoiceId == null) {
191	            throw new IllegalArgumentException("An invoice id is required");
192	        }
193	        InvoiceView current = find(invoiceId);
194	        // Payment is only allowed once an invoice has been sent.
195	        if (!"SENT".equals(current.getStatus())) {
196	            throw new IllegalStateException("An invoice can only be paid once it has been sent");
197	        }
198	        jdbc.update("UPDATE invoices SET status = 'PAID' WHERE id = ?", invoiceId);
199	        InvoiceView invoice = find(invoiceId);
200	        audit.record("INVOICE_PAID id=" + invoice.getId() + " amount="
201	                + invoice.getAmount().setScale(2));
202	        return invoice;
203	    }
204	
205	    /** The line items of an invoice, in the order they were added. */
206	    @Transactional(readOnly = true)
207	    public List<LineItemView> listLineItems(Long invoiceId) {
208	        return jdbc.query(
209	                "SELECT id, invoice_id, description, qty, unit, unit_price FROM line_items WHERE invoice_id = ? ORDER BY id ASC",
210	                (rs, i) -> new LineItemView(rs.getLong("id"), rs.getLong("invoice_id"),
211	                        rs.getString("description"), rs.getInt("qty"), rs.getString("unit"),
212	                        rs.getBigDecimal("unit_price")),
213	                invoiceId);
214	    }
215	
216	    /**
217	     * Add one line item to an invoice, then re-derive the invoice's amount as the sum of each line's
218	     * quantity times unit price so the stored total stays in step. Returns the invoice's line items.
219	     */
220	    @Transactional
221	    public List<LineItemView> addLineItem(Long invoiceId, NewLineItem body) {
222	        if (invoiceId == null) {
223	            throw new IllegalArgumentException("An invoice id is required");
224	        }
225	        if (body == null || body.getDescription() == null || body.getDescription().isBlank()) {
226	            throw new IllegalArgumentException("A line item requires a description");
227	        }
228	        if (body.getQty() == null || body.getQty() <= 0) {
229	            throw new IllegalArgumentException("A line item requires a quantity greater than zero");
230	        }
231	        if (body.getUnitPrice() == null || body.getUnitPrice().signum() < 0) {
232	            throw new IllegalArgumentException("A line item requires a unit price that is not negative");
233	        }
234	        LineItem lineItem = new LineItem();
235	        lineItem.setInvoiceId(invoiceId);
236	        lineItem.setDescription(body.getDescription());
237	        lineItem.setQty(body.getQty());
238	        // The unit the quantity is counted in; default to a generic "unit" when none is given.
239	        String unit = body.getUnit() == null || body.getUnit().isBlank() ? "unit" : body.getUnit().trim();
240	        lineItem.setUnit(unit);
241	        lineItem.setUnitPrice(body.getUnitPrice());
242	        lineItemRepository.save(lineItem);
243	        jdbc.update(
244	                "UPDATE invoices SET amount = COALESCE((SELECT SUM(qty * unit_price) FROM line_items WHERE invoice_id = ?), 0) WHERE id = ?",
245	                invoiceId, invoiceId);
246	        return listLineItems(invoiceId);
247	    }
248	
249	    /**
250	     * Remove one line item from an invoice, then re-derive the invoice's amount as the sum of each
251	     * remaining line's quantity times unit price so the stored total stays in step. Returns the
252	     * invoice's remaining line items.
253	     */
254	    @Transactional
255	    public List<LineItemView> removeLineItem(Long invoiceId, Long lineItemId) {
256	        if (invoiceId == null) {
257	            throw new IllegalArgumentException("An invoice id is required");
258	        }
259	        if (lineItemId == null) {
260	            throw new IllegalArgumentException("A line item id is required");
261	        }
262	        jdbc.update("DELETE FROM line_items WHERE id = ? AND invoice_id = ?", lineItemId, invoiceId);
263	        jdbc.update(
264	                "UPDATE invoices SET amount = COALESCE((SELECT SUM(qty * unit_price) FROM line_items WHERE invoice_id = ?), 0) WHERE id = ?",
265	                invoiceId, invoiceId);
266	        return listLineItems(invoiceId);
267	    }
268	
269	    /** The payments a client has made on an invoice, in the order they were recorded. */
270	    @Transactional(readOnly = true)
271	    public List<PaymentView> listPayments(Long invoiceId) {
272	        return jdbc.query(
273	                "SELECT id, invoice_id, amount, paid_date FROM payments WHERE invoice_id = ? ORDER BY id ASC",
274	                (rs, i) -> new PaymentView(rs.getLong("id"), rs.getLong("invoice_id"),
275	                        rs.getBigDecimal("amount"), rs.getDate("paid_date").toLocalDate().toString()),
276	                invoiceId);
277	    }
278	
279	    /** Record one payment a client has made against an invoice. Returns the invoice's payments. */
280	    @Transactional
281	    public List<PaymentView> addPayment(Long invoiceId, NewPayment body) {
282	        if (invoiceId == null) {
283	            throw new IllegalArgumentException("An invoice id is required");
284	        }
285	        if (body == null || body.getAmount() == null || body.getAmount().signum() <= 0) {
286	            throw new IllegalArgumentException("A payment requires an amount greater than zero");
287	        }
288	        if (body.getDate() == null || body.getDate().isBlank()) {
289	            throw new IllegalArgumentException("A payment requires a date");
290	        }
291	        Payment payment = new Payment();
292	        payment.setInvoiceId(invoiceId);
293	        payment.setAmount(body.getAmount());
294	        payment.setPaidDate(LocalDate.parse(body.getDate()));
295	        Payment saved = paymentRepository.save(payment);
296	        audit.record("PAYMENT_RECORDED id=" + saved.getId() + " amount="
297	                + body.getAmount().setScale(2));
298	        return listPayments(invoiceId);
299	    }
300	
301	    /** One invoice, with its status worked out from the payments recorded against it. */
302	    @Transactional(readOnly = true)
303	    public InvoiceView get(Long invoiceId) {
304	        if (invoiceId == null) {
305	            throw new IllegalArgumentException("An invoice id is required");
306	        }
307	        return find(invoiceId);
308	    }
309	
310	    private InvoiceView find(Long invoiceId) {
311	        return jdbc.queryForObject(DUE_AWARE_SELECT + "WHERE i.id = ?", INVOICE_MAPPER, invoiceId);
312	    }
313	}
